      hu: "Pakisztán legnagyobb és legforgalmasabb tengeri kikötője, amely az ország kereskedelmének jelentős részét bonyolítja. Kapu az Arab-tenger felé és a nemzetközi tengeri szállítás kulcsfontosságú csomópontja.",
      ro: "Cel mai mare și mai aglomerat port maritim din Pakistan, gestionând o parte semnificativă a comerțului național. O poartă către Marea Arabiei și un nod vital pentru transportul maritim internațional.",
      en: "Pakistan's largest and busiest seaport, handling a significant portion of the nation's trade. A gateway to the Arabian Sea and a vital hub for international maritime transport.",
      es: "El puerto marítimo más grande y concurrido de Pakistán, que maneja una parte significativa del comercio nacional. Es la puerta de entrada al Mar Arábigo y un nodo vital para el tráfico internacional.",
      pt: "O porto marítimo maior e mais movimentado do Paquistão, que movimenta uma parte significativa do comércio nacional. É a porta de entrada para o Mar Arábico e um nó vital para o tráfego internacional.",
      fr: "Le port de commerce le plus grand et le plus actif du Pakistan, traitant une part importante du commerce national. Une porte sur la mer d'Arabie et un hub majeur pour le trafic maritime international.",
