      de: "Pakistans erster in Privatbesitz befindlicher Flughafen, der von der örtlichen Geschäftsgemeinschaft zur Förderung von Exporten gebaut wurde. Er erleichtert den schnellen Transport von Fracht, insbesondere von verderblichen Waren und Industriegütern.",
      hu: "Pakisztán első magántulajdonban lévő repülőtere, amelyet a helyi üzleti közösség épített az export előmozdítása érdekében. Megkönnyíti a rakományok, különösen a romlandó áruk és ipari termékek gyors szállítását.",
      ro: "Primul aeroport privat din Pakistan, construit de comunitatea de afaceri locală pentru a stimula exporturile. Acesta facilitează transportul rapid de mărfuri, în special bunuri perisabile și produse industriale.",
      en: "Pakistan's first privately-owned airport, built by the local business community to boost exports. It facilitates the swift transport of cargo, especially perishable goods and industrial products.",
      es: "El primer aeropuerto de Pakistán de propiedad privada, construido por la comunidad empresarial local para promover las exportaciones. Facilita el transporte rápido de carga, especialmente de bienes perecederos e industriales.",
      pt: "O primeiro aeroporto de propriedade privada do Paquistão, construído pela comunidade empresarial local para promover as exportações. Facilita o transporte rápido de carga, especialmente de bens perecíveis e industriais.",
      fr: "Le premier aéroport privé du Pakistan, construit par la communauté d'affaires locale pour promouvoir les exportations. Il facilite le transport rapide du fret, en particulier des denrées périssables et des produits industriels.",
